def lcs_brute(text1, text2, i, j):
    if i == len(text1) or j == len(text2):
        return 0
    if text1[i] == text2[j]:
        return 1 + lcs_brute(text1, text2, i + 1, j + 1)          # extend the match
    return max(lcs_brute(text1, text2, i + 1, j), lcs_brute(text1, text2, i, j + 1))   # drop one side

